insert into public.products (name, description, price, category, image_url, stock, is_active)
select seed.name, seed.description, seed.price, seed.category, seed.image_url, 10, true
from jsonb_to_recordset($seed$[{"name":"Pink Princess Party Frock","category":"Party Wear","price":4500,"description":"A beautiful layered tulle party frock with delicate detailing, perfect for birthdays and special occasions.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQiRZ1yeLXb0qPBgaOqDQQcTg5QwFrMTJSyydnddrDVtw&s"},{"name":"Floral Garden Frock","category":"Casual Wear","price":2800,"description":"A charming floral frock designed for comfortable everyday styling.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS3D1WIxyhKluJlMXZxROIQTskFO3ZpHvSyVLWWywqm1A&s=10"},{"name":"Dreamy Lavender Dress","category":"Party Wear","price":5200,"description":"A dreamy lavender occasion dress with a soft, elegant silhouette.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSG40w2VsD5cbfuuy4dMazO--0I6VIgSoDewOQ1Fdwn8Abk5xXwJJIzinfa&s=10"},{"name":"Birthday Princess Gown","category":"Birthday Wear","price":6500,"description":"An elegant princess gown for making birthday celebrations unforgettable.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRH15oYTNtUCO2x2zeB2vNyvqeQ2NAWi9oto05ZPisoqA&s"},{"name":"Little Rose Party Dress","category":"Party Wear","price":3900,"description":"A sweet rose-pink frock with a lovely party-ready design.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRNto7DaPZFnMgH0YM6DwqT9-zU6OYuhBztM9M7EjC-Dw&s=10"},{"name":"Elegant White Angel Frock","category":"Wedding Wear","price":5800,"description":"A graceful white occasion frock for weddings and memorable family events.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTlrNFd3dJob1alr1skx2T82Ak2eCGuCdfkl2sYLQtvcQ&s=10"},{"name":"Blush Pink Tulle Frock","category":"Party Wear","price":4200,"description":"A soft blush tulle frock with a twirl-worthy skirt for parties and celebrations.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSaWaOz8P59JBxGLIAMnBRYbo8RrHs3TgqaFfoiwU9qyg&s"},{"name":"Red Dream Party Dress","category":"Party Wear","price":4900,"description":"A dreamy lavender party dress with a floaty skirt and a comfortable fit.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTx5dhodaf_RxX8Glsorn6HvqxC3odrrG3QfOcSuOkgpA&s"},{"name":"Little Daisy Summer Frock","category":"Casual Wear","price":2600,"description":"A light and cheerful floral frock made for sunny days and family outings.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQNvojPyDhcBI_fWcJ3JvEVssp69nkgYc_-aq0rssJLSQ&s"},{"name":"Ruby Red Birthday Frock","category":"Birthday Wear","price":5600,"description":"A bright birthday frock with a festive look for a day full of happy memories.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRInECpF6qzRVUZcJlvUyVqDud68dHsy3U2I5ZyT10FGLI-VrbNZTD2ySQ&s=10"},{"name":"Pearl White Wedding Frock","category":"Wedding Wear","price":6900,"description":"An elegant pearl-white frock with a graceful silhouette for weddings and formal events.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTuhHu7COChGefJp-S_Bda_syf4zCBeaPHHNDaU54GXoA&s=10"},{"name":"Peach Blossom Party Frock","category":"Party Wear","price":3900,"description":"A sweet peach-colored frock with delicate floral charm for little celebrations.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTi1wlUblUFha6pP09hZw-_Sl7cn3CHOusUjfTkASovteZD1RTUIT4yhwPj&s=10"},{"name":"Sky Blue Picnic Dress","category":"Casual Wear","price":2500,"description":"An easy-to-wear sky-blue dress for picnics, playdates, and everyday adventures.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQp6x4O31_133BuIUV5-S54Tcqwr-nedO6jr1pBwi0Sfw&s=10"},{"name":"Golden Star Birthday Gown","category":"Birthday Wear","price":6200,"description":"A golden party gown with a magical look for birthdays and special milestones.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQS3zTFzik0Cpetu6Qi7YaYDZCHSlJEuwlh6o1aJ2RUV7RpdcxP6H12sys&s=10"},{"name":"Rose Garden Floral Frock","category":"Casual Wear","price":2900,"description":"A pretty rose-print frock with a relaxed fit for comfortable all-day wear.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR5UaOY8zlqojHFo1szfNru_C7fyuNi585RaAbZF6bgPA&s"},{"name":"Mint Candy Party Dress","category":"Party Wear","price":4300,"description":"A fresh mint-green dress with a lovely party-ready shape and soft feel.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRCevuyP__UtCNZr0Wx_7kpS2ZUfTj7m6xRuviGi11nWg&s=10"},{"name":"Royal Blue Celebration Frock","category":"Birthday Wear","price":5400,"description":"A bright royal-blue frock designed to stand out at birthdays and family celebrations.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ1osQbS7p9ooDwRIas0aCK_PeX_Vvq_pfVCNCmivLUvA&s=10"},{"name":"Buttercup Yellow Day Frock","category":"Casual Wear","price":2700,"description":"A cheerful yellow frock for playtime, sunny walks, and relaxed weekends.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR80DJgU4u-x9G1x11w3CC0uUET38VTubbJ2GJAIoA_Fw&s=10"},{"name":"Cherry Blossom Wedding Dress","category":"Wedding Wear","price":7200,"description":"A graceful blush occasion dress for weddings, Eid gatherings, and family portraits.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSHTuZpTD6P47Ydf3FGQ7lfIq7_ciUCeZEFcv-O12O_2A&s=10"},{"name":"Lilac Butterfly Party Frock","category":"Party Wear","price":4500,"description":"A lilac party frock with a playful, twirl-friendly silhouette for little dreamers.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSz4Y09x3Rh5FgSRdYRj_Twyy19C8t49fKIJLANXQrwEw&s=10"},{"name":"Ivory Lace Angel Dress","category":"Wedding Wear","price":6800,"description":"A lovely ivory dress with a delicate look for wedding ceremonies and formal occasions.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSATM0CM1Z9TL6VzFOvYlTFRHZQxHushYqXh_nTquJotg&s"},{"name":"Coral Sunset Birthday Dress","category":"Birthday Wear","price":5100,"description":"A vibrant coral dress for birthday parties, cake-cutting, and picture-perfect moments.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT-d7mNH8goXoPXsgTylzG2dbtkkZVGF_uD_-cDL5IhGg&s=10"},{"name":"Ocean Breeze Everyday Frock","category":"Casual Wear","price":2400,"description":"A breezy blue frock that keeps little ones comfortable through busy days.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTCasab3VNdPrqNYMSC5x3I63NYYeE_VmrIspbxUBczUA&s=10"},{"name":"Ruby Rose Festive Gown","category":"Wedding Wear","price":7500,"description":"A rich ruby occasion gown for weddings, festive dinners, and cherished family events.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSQpr-dpZ2gsZ4Get1Q4mDxoOG51NPTT1LNg_smhhh9Kg&s"},{"name":"Candy Pink Party Frock","category":"Party Wear","price":4100,"description":"A lovely candy-pink frock for party days, playdates, and everything in between.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQtT8Fmsw_NMtNMQdhkWwOvOjU5SovWhsjNx7B5edlgug&s=10"},{"name":"Snowflake Winter Party Dress","category":"Party Wear","price":4700,"description":"A sweet winter-white party dress for family get-togethers and festive celebrations.","image_url":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTyjhooKu96pv10ZgAwiU-GDbaaS8dqGrQTbnhCgi07Bw&s=10"}]$seed$::jsonb) as seed(
  name text, category text, price numeric(10,2), description text, image_url text
)
where not exists (
  select 1 from public.products as existing
  where lower(existing.name) = lower(seed.name)
);
